sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);

	test.SetResult(true);

	function TestCase_AiToolGetBusinessProcess(vBusinessProcess,vExpected)
	{
		function TestCase_AiToolGetBusinessProcess_CheckResult(vInput,vExpected,vResult)
		{
			if (vExpected == false)
			{
				if (x_snc_devtools.GetValue(vResult,'message') != 'The Business Process could not be found.')
				{
					return false;
				}
				return true;
			}
			if (x_snc_devtools.IsObject(vResult) == false)
			{
				return false;
			}
			return true;
		}

		test.TestCase(
			'Function AiToolGetBusinessProcess()',
			AiToolGetBusinessProcess,
			{
				'vBusinessProcess': vBusinessProcess
			},
			vExpected,
			TestCase_AiToolGetBusinessProcess_CheckResult);
	}

	TestCase_AiToolGetBusinessProcess(null,false);

	var grBP = new GlideRecord('x_snc_agenticbpc_business_process');
	grBP.name = 'Simple Task';
	var strBusinessProcessSysId = grBP.insert();
	TestCase_AiToolGetBusinessProcess(strBusinessProcessSysId,true);

	grBP.json = x_snc_devtools.MakeJson(x_snc_devtools.BusinessProcessGetExample());
	grBP.update();
	TestCase_AiToolGetBusinessProcess(strBusinessProcessSysId,true);


	return test.GetResult();

})(outputs, steps, stepResult, assertEqual);
